fn count_primes_below(n: u16) -> u16 {
    if n <= 2 {
        return 0;
    }
    let mut count: u16 = 0;
    let mut i: u16 = 2;
    while i < n bound 2000 {
        if is_prime(i) {
            count = count + 1;
        }
        i = i + 1;
    }
    return count;
}

fn is_prime(x: u16) -> bool {
    if x <= 1 {
        return false;
    }
    if x == 2 {
        return true;
    }
    if x % 2 == 0 {
        return false;
    }
    let mut i: u16 = 3;
    while i * i <= x bound 2000 {
        if x % i == 0 {
            return false;
        }
        i = i + 2;
    }
    return true;
}
